import { InterviewQuestion } from '@/types/interview';

const CURATED_INTERVIEW_EXTENSION: InterviewQuestion[] = [
  // ==========================================
  // STAGE 1: HR & CULTURE SCREENING
  // ==========================================
  { id: 'hr-003', role: 'Fullstack Software Engineer', stage: 'HR & Culture Screening', competency: 'Career Motivation & Role Fit', difficulty: 'Entry', questionType: 'HR / Cultural Fit', question: 'What attracted you to fullstack engineering, and which part of the product-development lifecycle are you most eager to own?', expectedCompetencies: ['Clear motivation', 'Understanding of frontend and backend collaboration', 'Growth mindset'], evaluationCriteria: ['Connects interests to the role', 'Names concrete skills or experiences', 'Sets realistic learning goals'], idealStarResponse: 'I enjoy taking an idea from an accessible interface through a dependable API to measurable user value. In a university project, I owned a React and Node feature end to end, learned where my API contract created friction for the UI, and reduced the onboarding flow from five steps to three. I want a role where I can deepen that product-minded ownership while learning from experienced engineers.', weakResponseExample: 'I picked fullstack because it seems like the easiest way to get a job and I can do a little of everything.' },
  { id: 'hr-004', role: 'Fullstack Software Engineer', stage: 'HR & Culture Screening', competency: 'Learning Agility', difficulty: 'Entry', questionType: 'HR / Cultural Fit', question: 'Tell me about a technology you had to learn quickly to deliver a project. How did you approach the learning curve?', expectedCompetencies: ['Structured learning approach', 'Resourcefulness', 'Reflection on outcomes'], evaluationCriteria: ['Explains the initial gap', 'Describes practical learning steps', 'Connects learning to delivery'], idealStarResponse: 'For a student capstone, I needed to add authentication but had not used OAuth before. I read the provider documentation, built a small spike with test accounts, and asked a mentor to review the threat model before integrating it. We delivered login on time, and I documented the callback and token-refresh flow so the next teammate could maintain it.', weakResponseExample: 'I watched a few videos and eventually copied code until it worked.' },
  { id: 'hr-005', role: 'Cloud & DevOps Engineer', stage: 'HR & Culture Screening', competency: 'Operational Mindset', difficulty: 'Mid-Level', questionType: 'HR / Cultural Fit', question: 'What does ownership mean to you for a service after it has been deployed?', expectedCompetencies: ['Production accountability', 'Observability mindset', 'Customer impact awareness'], evaluationCriteria: ['Moves beyond deployment', 'Mentions monitoring and incident response', 'Balances reliability with delivery'], idealStarResponse: 'Ownership starts at design and continues through the service lifecycle. For me that means defining SLOs, dashboards, runbooks, safe deployment and rollback paths, and reviewing incidents for systemic improvements. A deployment is successful only when users receive a reliable outcome and the team can operate the service confidently.', weakResponseExample: 'Once the CI pipeline is green, operations can take over from engineering.' },
  { id: 'hr-006', role: 'AI & Data Platform Engineer', stage: 'HR & Culture Screening', competency: 'Responsible AI Mindset', difficulty: 'Mid-Level', questionType: 'HR / Cultural Fit', question: 'What interests you about building AI/ML products, and what responsibilities come with deploying them?', expectedCompetencies: ['User-value orientation', 'Awareness of data and model risk', 'Practical governance'], evaluationCriteria: ['Explains a concrete motivation', 'Mentions privacy, bias, or evaluation', 'Recognizes monitoring after launch'], idealStarResponse: 'I am interested in AI when it removes repetitive work or improves a decision, not simply because it is novel. In a document-classification project, I measured errors by document type, kept human review for low-confidence results, and avoided storing unnecessary personal data. In production I would continue to monitor drift, quality, and user feedback so the system remains useful and accountable.', weakResponseExample: 'AI is the future, so I want to use the latest model for every problem.' },
  { id: 'hr-007', role: 'Telecom & Network Systems Engineer', stage: 'HR & Culture Screening', competency: 'Domain Curiosity', difficulty: 'Entry', questionType: 'HR / Cultural Fit', question: 'What interests you about network engineering, and how do you keep up with changes in connectivity technology?', expectedCompetencies: ['Genuine domain interest', 'Self-directed learning', 'Connection to user impact'], evaluationCriteria: ['Explains why networking matters', 'Names credible learning habits', 'Shows curiosity about reliability or scale'], idealStarResponse: 'I am drawn to networking because invisible infrastructure determines whether people and businesses can communicate reliably. I reinforce coursework by building small labs, reading vendor and IETF documentation, and following how 5G, cloud networking, and automation change operations. I particularly enjoy turning packet-level evidence into a practical reliability improvement.', weakResponseExample: 'Networks are everywhere, and I heard the field pays well.' },
  { id: 'hr-008', role: 'Fullstack Software Engineer', stage: 'HR & Culture Screening', competency: 'Feedback Receptiveness', difficulty: 'Mid-Level', questionType: 'HR / Cultural Fit', question: 'Describe feedback that changed how you work as an engineer.', expectedCompetencies: ['Coachability', 'Specific behavior change', 'Measurable improvement'], evaluationCriteria: ['States feedback without defensiveness', 'Explains the changed practice', 'Shows impact on team or users'], idealStarResponse: 'A reviewer told me my pull requests were difficult to review because they combined refactoring with product changes. I started separating mechanical changes, adding concise context and test evidence, and requesting early design feedback for larger work. Review turnaround improved, and a teammate adopted the same template for our repository.', weakResponseExample: 'I rarely get negative feedback because I make sure my work is correct before anyone sees it.' },
  { id: 'hr-009', role: 'Cloud & DevOps Engineer', stage: 'HR & Culture Screening', competency: 'Collaboration Across Functions', difficulty: 'Senior', questionType: 'HR / Cultural Fit', question: 'How do you partner with application engineers when a reliability requirement conflicts with a delivery deadline?', expectedCompetencies: ['Constructive negotiation', 'Risk communication', 'Incremental delivery'], evaluationCriteria: ['Frames trade-offs in user impact', 'Offers options rather than a veto', 'Defines an accountable follow-up'], idealStarResponse: 'I make the risk concrete, such as the expected blast radius or missing rollback path, then propose the smallest safe slice. For example, I have paired a guarded feature flag release with a follow-up resilience milestone instead of blocking an urgent customer fix. We document the accepted risk, assign an owner, and verify the mitigation rather than letting debt disappear into the backlog.', weakResponseExample: 'Platform rules are platform rules, so I tell product the release cannot happen.' },
  { id: 'hr-010', role: 'AI & Data Platform Engineer', stage: 'HR & Culture Screening', competency: 'Data Quality Ownership', difficulty: 'Senior', questionType: 'HR / Cultural Fit', question: 'How do you explain the importance of data quality to a stakeholder who wants to move quickly?', expectedCompetencies: ['Business framing', 'Risk prioritization', 'Pragmatic controls'], evaluationCriteria: ['Connects quality to decisions or user trust', 'Prioritizes critical fields', 'Proposes measurable safeguards'], idealStarResponse: 'I explain that a fast pipeline with incorrect data only accelerates the wrong decision. I identify the fields that affect money, eligibility, or customer experience, add freshness and validity checks around them, and publish a simple quality scorecard. That lets us move quickly on low-risk data while protecting the inputs that make a model or dashboard trustworthy.', weakResponseExample: 'Data quality is important, so we should clean every table before doing anything else.' },
  { id: 'hr-011', role: 'Fullstack Software Engineer', stage: 'HR & Culture Screening', competency: 'Product Empathy', difficulty: 'Entry', questionType: 'HR / Cultural Fit', question: 'How do you make sure the feature you build solves a user problem instead of only satisfying a ticket?', expectedCompetencies: ['User empathy', 'Clarifying questions', 'Outcome orientation'], evaluationCriteria: ['Seeks context before implementation', 'Uses feedback or metrics', 'Recognizes accessibility and edge cases'], idealStarResponse: 'I start by asking who experiences the problem, what success looks like, and what constraints matter. For a form feature, I would review the current flow, validate assumptions with product or support, and consider accessibility and error states before coding. After release, I would check completion or support metrics to learn whether the change actually helped.', weakResponseExample: 'If the acceptance criteria are met, the feature is done.' },
  { id: 'hr-012', role: 'Telecom & Network Systems Engineer', stage: 'HR & Culture Screening', competency: 'Safety and Change Discipline', difficulty: 'Senior', questionType: 'HR / Cultural Fit', question: 'How do you balance urgency with caution when proposing a change to a production network?', expectedCompetencies: ['Risk assessment', 'Change management', 'Rollback planning'], evaluationCriteria: ['Identifies blast radius', 'Uses staged validation', 'Communicates decision criteria'], idealStarResponse: 'I start with impact and reversibility: which customers, services, and dependencies can be affected? I validate the change in a representative environment, schedule an appropriate window, define success and rollback signals, and make sure stakeholders know the plan. In an incident I may move faster, but I still make the smallest reversible change first and capture decisions for the follow-up review.', weakResponseExample: 'If the change is urgent, it is better to apply it everywhere immediately and fix problems later.' },
  { id: 'hr-013', role: 'Engineering Manager / Tech Lead', stage: 'HR & Culture Screening', competency: 'Leadership Philosophy', difficulty: 'Lead / Principal', questionType: 'HR / Cultural Fit', question: 'What kind of engineering culture do you deliberately create, and how do you know it is working?', expectedCompetencies: ['Leadership clarity', 'Psychological safety', 'Outcome and quality balance'], evaluationCriteria: ['Names concrete rituals or systems', 'Balances accountability and safety', 'Uses observable health signals'], idealStarResponse: 'I aim for a culture where people surface risks early, challenge ideas respectfully, and remain accountable for outcomes. I reinforce it through clear decision records, blameless incident reviews, regular coaching, and quality signals such as delivery predictability, review latency, reliability, and team-retention patterns. Culture is working when hard information reaches the team before it becomes an outage or resignation.', weakResponseExample: 'A good culture is one where everyone is friendly and works hard.' },
  { id: 'hr-014', role: 'Fullstack Software Engineer', stage: 'HR & Culture Screening', competency: 'Career Decision Making', difficulty: 'Senior', questionType: 'HR / Cultural Fit', question: 'What are you looking for in your next engineering role, and how will you evaluate whether it is the right fit?', expectedCompetencies: ['Self-awareness', 'Values alignment', 'Professional specificity'], evaluationCriteria: ['Gives role-relevant priorities', 'Balances growth and contribution', 'Asks thoughtful evaluation questions'], idealStarResponse: 'I look for a team that treats product outcomes, code quality, and learning as shared responsibilities. I evaluate fit by asking how decisions are made, how production ownership works, what feedback looks like, and which customer outcomes the team owns. I want to contribute my experience in reliable web systems while stretching into larger-scale design and mentoring.', weakResponseExample: 'I mainly want the title, compensation, and the ability to work with any technology I choose.' },
  { id: 'hr-015', role: 'AI & Data Platform Engineer', stage: 'HR & Culture Screening', competency: 'Technical Communication', difficulty: 'Lead / Principal', questionType: 'HR / Cultural Fit', question: 'How do you build trust with product, legal, and engineering partners before launching a high-impact ML feature?', expectedCompetencies: ['Cross-functional communication', 'Model-risk governance', 'Launch accountability'], evaluationCriteria: ['Sets shared success and risk criteria', 'Explains transparency mechanisms', 'Includes monitoring and escalation'], idealStarResponse: 'I involve partners before the model is treated as a finished artifact. We agree on the decision it supports, unacceptable failure modes, data permissions, evaluation slices, and human escalation path. I publish a concise model card and launch plan with owners for monitoring, feedback, and rollback, so each group can see both the value and the controls.', weakResponseExample: 'I would let the model team finish the work first and only bring in legal once the feature is ready.' },

  // ==========================================
  // STAGE 2: BEHAVIORAL & STAR COMPETENCY
  // ==========================================
  { id: 'beh-003', role: 'Fullstack Software Engineer', stage: 'Behavioral & STAR Competency', competency: 'Ambiguous Problem Solving', difficulty: 'Entry', questionType: 'Behavioral', question: 'Tell me about a time you were given an ambiguous engineering task. How did you turn it into an actionable plan?', expectedCompetencies: ['STAR narrative', 'Requirement discovery', 'Incremental execution'], evaluationCriteria: ['Defines the ambiguity', 'Shows stakeholder clarification and a plan', 'Reports a concrete result'], idealStarResponse: 'Situation: Our team was asked to improve a slow dashboard without a clear definition of slow. Task: I needed to turn that request into a deliverable. Action: I measured page timings, interviewed two users, identified a blocking API call, and proposed a staged fix with a loading state and paginated endpoint. Result: the initial view became usable in under two seconds and the team adopted the measurement as an acceptance criterion.', weakResponseExample: 'The requirements were unclear, so I waited until the product manager told me exactly what to build.' },
  { id: 'beh-004', role: 'Fullstack Software Engineer', stage: 'Behavioral & STAR Competency', competency: 'Quality Under Delivery Pressure', difficulty: 'Mid-Level', questionType: 'Behavioral', question: 'Describe a time you protected quality while delivering an urgent feature.', expectedCompetencies: ['STAR structure', 'Risk-based prioritization', 'Testing discipline'], evaluationCriteria: ['Explains the deadline and risk', 'Describes a safe delivery strategy', 'Quantifies quality or delivery outcome'], idealStarResponse: 'Situation: A customer needed a reporting export before month end, but the requested path touched permissions. Task: I had to ship quickly without exposing data. Action: I narrowed the first release to existing roles, added authorization tests and audit logs, and used a feature flag while a teammate reviewed the access rules. Result: we shipped two days early with no permission incidents and completed the broader role model in the next sprint.', weakResponseExample: 'I skipped testing because the customer needed it, then planned to fix anything they found.' },
  { id: 'beh-005', role: 'Cloud & DevOps Engineer', stage: 'Behavioral & STAR Competency', competency: 'Incident Communication', difficulty: 'Mid-Level', questionType: 'Behavioral', question: 'Tell me about a production incident where clear communication changed the outcome.', expectedCompetencies: ['STAR narrative', 'Stakeholder updates', 'Operational ownership'], evaluationCriteria: ['Establishes impact and role', 'Explains update cadence and mitigation', 'Shows measurable recovery or learning'], idealStarResponse: 'Situation: A deployment caused intermittent checkout failures during a campaign. Task: As incident coordinator, I had to restore service and keep support informed. Action: I opened a channel, assigned investigation and communications owners, posted impact updates every ten minutes, and rolled back once error rate crossed our threshold. Result: errors returned to baseline in twelve minutes, support could answer customers consistently, and we added a canary error-budget gate.', weakResponseExample: 'I focused on fixing it and did not want to distract people by telling anyone until it was over.' },
  { id: 'beh-006', role: 'AI & Data Platform Engineer', stage: 'Behavioral & STAR Competency', competency: 'Experimentation and Learning', difficulty: 'Mid-Level', questionType: 'Behavioral', question: 'Describe an ML or analytics experiment that did not produce the expected result. What did you do next?', expectedCompetencies: ['Scientific thinking', 'Ownership', 'Evidence-based iteration'], evaluationCriteria: ['States a hypothesis and outcome', 'Diagnoses with data', 'Explains a measured next step'], idealStarResponse: 'Situation: We expected a recommendation model to increase repeat visits, but the offline lift did not appear in the first live cohort. Task: I needed to understand whether the issue was model quality or experiment design. Action: I checked sample-ratio mismatch, segmented new and returning users, and found sparse history for new users. Result: we added a popularity fallback and a cold-start feature set; the next experiment improved returning-user engagement without degrading the new-user experience.', weakResponseExample: 'The model did not work, so we changed the algorithm and ran it again.' },
  { id: 'beh-007', role: 'Telecom & Network Systems Engineer', stage: 'Behavioral & STAR Competency', competency: 'Root Cause Analysis', difficulty: 'Senior', questionType: 'Behavioral', question: 'Describe a recurring network issue you investigated. How did you separate the symptom from the root cause?', expectedCompetencies: ['STAR method', 'Evidence-led troubleshooting', 'Preventative action'], evaluationCriteria: ['Distinguishes symptom and cause', 'Uses telemetry or controlled tests', 'Provides lasting measurable outcome'], idealStarResponse: 'Situation: Several sites showed periodic packet loss, and restarts only hid it temporarily. Task: I needed to identify the shared cause. Action: I correlated interface errors, timing, and configuration changes, captured traffic during the event, and isolated an MTU mismatch on a transit path. Result: after correcting the configuration and adding pre-change validation, packet loss alerts dropped to baseline and the issue did not recur over the next quarter.', weakResponseExample: 'I restarted the affected equipment each time and it usually solved the problem.' },
  { id: 'beh-008', role: 'Fullstack Software Engineer', stage: 'Behavioral & STAR Competency', competency: 'Customer Empathy', difficulty: 'Entry', questionType: 'Behavioral', question: 'Tell me about a time feedback from a user changed a feature you were building.', expectedCompetencies: ['Listening', 'Iteration', 'User outcome focus'], evaluationCriteria: ['Explains the original assumption', 'Shows how feedback was gathered', 'Describes the resulting improvement'], idealStarResponse: 'Situation: We assumed users wanted more filtering options in a search screen. Task: I was implementing the filter panel. Action: During a usability review, users said they first needed to understand why a result appeared, so I added concise matched-term explanations before expanding the filters. Result: testers completed the task faster, and support requests about search relevance declined after release.', weakResponseExample: 'Users asked for a change, so I added every option they requested.' },
  { id: 'beh-009', role: 'Cloud & DevOps Engineer', stage: 'Behavioral & STAR Competency', competency: 'Influencing Without Authority', difficulty: 'Senior', questionType: 'Behavioral', question: 'Describe a time you persuaded a team to adopt a reliability practice they initially resisted.', expectedCompetencies: ['STAR narrative', 'Influence through evidence', 'Sustainable adoption'], evaluationCriteria: ['Explains resistance fairly', 'Uses data or a low-risk trial', 'Shows adoption impact'], idealStarResponse: 'Situation: Teams viewed load testing as release friction after a capacity incident. Task: I needed to make it practical rather than mandate it. Action: I piloted a small k6 test in one service, showed that it found a connection-pool limit before launch, and provided a reusable CI template. Result: three services adopted the check within a quarter and we caught two capacity regressions before production.', weakResponseExample: 'I escalated to management until everyone was forced to use my process.' },
  { id: 'beh-010', role: 'AI & Data Platform Engineer', stage: 'Behavioral & STAR Competency', competency: 'Ethical Judgment', difficulty: 'Senior', questionType: 'Behavioral', question: 'Tell me about a time you raised a concern about data use, model behavior, or privacy.', expectedCompetencies: ['Ethical reasoning', 'Constructive escalation', 'Practical remediation'], evaluationCriteria: ['Names the risk precisely', 'Explains collaborative action', 'Shows an outcome that protects users'], idealStarResponse: 'Situation: A proposed model feature included free-text customer notes containing sensitive information. Task: I needed to raise the privacy risk without stopping useful experimentation. Action: I documented the data elements, involved privacy partners, and proposed redaction plus a narrower feature set with access controls. Result: the team launched a safer version on schedule and added a review checklist for future datasets.', weakResponseExample: 'I assumed compliance had approved it because the data was already in our system.' },
  { id: 'beh-011', role: 'Fullstack Software Engineer', stage: 'Behavioral & STAR Competency', competency: 'Code Review Collaboration', difficulty: 'Mid-Level', questionType: 'Behavioral', question: 'Describe a difficult code review conversation and how you reached a constructive outcome.', expectedCompetencies: ['Respectful communication', 'Technical reasoning', 'Shared ownership'], evaluationCriteria: ['Avoids blame', 'Explains trade-offs with evidence', 'Shows agreement or learning'], idealStarResponse: 'Situation: A reviewer questioned my caching design because invalidation could serve stale account data. Task: I needed to resolve the concern without turning the review into a debate. Action: I wrote down the consistency requirement, compared a short TTL with event invalidation, and asked the reviewer to pair on a failure-mode test. Result: we chose event invalidation for sensitive fields, added metrics for stale reads, and the review improved the design before release.', weakResponseExample: 'The reviewer was blocking me, so I merged after getting another approval.' },
  { id: 'beh-012', role: 'Telecom & Network Systems Engineer', stage: 'Behavioral & STAR Competency', competency: 'Change Management', difficulty: 'Mid-Level', questionType: 'Behavioral', question: 'Tell me about a planned infrastructure change that did not go as expected. What did you do?', expectedCompetencies: ['STAR format', 'Rollback discipline', 'Learning from failure'], evaluationCriteria: ['Explains the planned safeguards', 'Describes decision-making during failure', 'Includes process improvement'], idealStarResponse: 'Situation: A routing-policy update passed lab validation but increased latency for one regional path in production. Task: I had to limit impact and diagnose the difference. Action: I paused the rollout, reverted the affected policy using the approved plan, compared production path attributes, and found an unmodeled upstream preference. Result: latency normalized within minutes, and we added production-like peer attributes to the validation checklist.', weakResponseExample: 'The change caused issues, so we left it overnight to see whether the network would settle.' },
  { id: 'beh-013', role: 'Engineering Manager / Tech Lead', stage: 'Behavioral & STAR Competency', competency: 'Delegation and Growth', difficulty: 'Lead / Principal', questionType: 'Behavioral', question: 'Describe how you delegated a critical project while remaining accountable for its outcome.', expectedCompetencies: ['Leadership judgment', 'Clear ownership', 'Coaching'], evaluationCriteria: ['Defines the stakes and delegated scope', 'Explains checkpoints without micromanaging', 'Shows outcome and growth'], idealStarResponse: 'Situation: We needed to replace a fragile deployment workflow before a major launch. Task: I wanted a senior engineer to lead it while retaining delivery accountability. Action: We agreed on success metrics, decision boundaries, and weekly risk reviews; I unblocked cross-team dependencies but let them own the design and demos. Result: the workflow shipped before the launch, rollback time fell materially, and the engineer became the team’s operational-design lead.', weakResponseExample: 'I assigned the project and only checked in once it was due.' },
  { id: 'beh-014', role: 'Fullstack Software Engineer', stage: 'Behavioral & STAR Competency', competency: 'Prioritization', difficulty: 'Senior', questionType: 'Behavioral', question: 'Tell me about a time you had to choose between fixing technical debt and delivering a requested feature.', expectedCompetencies: ['Trade-off analysis', 'Stakeholder alignment', 'Outcome measurement'], evaluationCriteria: ['Makes risks concrete', 'Proposes an incremental plan', 'Reports impact'], idealStarResponse: 'Situation: A feature request depended on a module with frequent regressions. Task: I had to balance the customer deadline with the risk of adding more change. Action: I quantified recent incident time, proposed a small boundary refactor that enabled the feature, and agreed with product to defer the broader cleanup. Result: we met the date without a regression and reduced future change effort by isolating the unstable dependency.', weakResponseExample: 'Technical debt is always important, so I delayed the feature until everything was cleaned up.' },
  { id: 'beh-015', role: 'AI & Data Platform Engineer', stage: 'Behavioral & STAR Competency', competency: 'Cross-Functional Delivery', difficulty: 'Lead / Principal', questionType: 'Behavioral', question: 'Describe a data or ML initiative where engineering, product, and operations had different definitions of success. How did you align them?', expectedCompetencies: ['STAR structure', 'Shared metric design', 'Cross-functional leadership'], evaluationCriteria: ['Identifies competing goals', 'Creates a common decision framework', 'Shows measured business and operational result'], idealStarResponse: 'Situation: Product wanted higher automation, operations wanted fewer false positives, and engineering wanted a maintainable model pipeline. Task: I had to make the launch criteria explicit. Action: I facilitated a working session that set precision, review-volume, latency, and rollback thresholds, then instrumented a shadow deployment against those metrics. Result: we launched only after meeting the agreed thresholds, reduced manual review volume, and retained an escalation path for uncertain cases.', weakResponseExample: 'Each team had its own goals, so I focused on whichever stakeholder was most senior.' },

  // ==========================================
  // STAGE 3: TECHNICAL & DOMAIN DEPTH
  // ==========================================
  { id: 'tech-004', role: 'Fullstack Software Engineer', stage: 'Technical & Domain Depth', competency: 'API Design and Versioning', difficulty: 'Mid-Level', questionType: 'Technical', question: 'How would you evolve a public REST API without breaking existing clients?', expectedCompetencies: ['Backward compatibility', 'Contract design', 'Deprecation strategy'], evaluationCriteria: ['Explains additive changes and versioning trade-offs', 'Mentions validation and documentation', 'Includes observability and migration'], idealStarResponse: 'I prefer additive, backward-compatible changes: optional fields, stable defaults, and clear schema validation. When a breaking change is unavoidable, I publish a versioned contract, migration guide, deprecation timeline, and usage telemetry so clients can move safely. Contract tests and consumer feedback help verify that the old path remains reliable until retirement.', weakResponseExample: 'I change the endpoint response and tell clients to update when they see errors.' },
  { id: 'tech-005', role: 'Fullstack Software Engineer', stage: 'Technical & Domain Depth', competency: 'Frontend Performance', difficulty: 'Mid-Level', questionType: 'Technical', question: 'A React application feels slow on first load and when filtering a large list. How would you diagnose and improve it?', expectedCompetencies: ['Browser profiling', 'Network and bundle analysis', 'Rendering optimization'], evaluationCriteria: ['Separates load and interaction issues', 'Mentions measurement before optimization', 'Uses appropriate caching, virtualization, or code splitting'], idealStarResponse: 'I first measure Core Web Vitals, bundle composition, network waterfalls, and React render profiles rather than guessing. For first load, I would remove unused dependencies, split noncritical routes, optimize images, and cache stable API data. For filtering, I would debounce input, avoid unnecessary rerenders, memoize expensive derived data where it helps, and virtualize large result sets while confirming improvements with real-device measurements.', weakResponseExample: 'I would add useMemo everywhere and increase the server size.' },
  { id: 'tech-006', role: 'Fullstack Software Engineer', stage: 'Technical & Domain Depth', competency: 'Authentication and Authorization', difficulty: 'Senior', questionType: 'Technical', question: 'Explain how you would secure a web application that uses a single-page frontend and a backend API.', expectedCompetencies: ['Authentication flow', 'Authorization enforcement', 'Web security controls'], evaluationCriteria: ['Distinguishes identity from permissions', 'Addresses token/session risks and CSRF/XSS', 'Enforces authorization server-side'], idealStarResponse: 'I choose a well-supported OAuth/OIDC flow and treat the backend as the authority for every protected action. Sessions or tokens are short-lived and stored with defenses appropriate to the architecture, while the API verifies issuer, audience, expiry, and scopes or roles. I combine that with server-side authorization checks, HTTPS, secure cookie settings where applicable, CSRF protection for cookie-authenticated mutations, input validation, CSP, and audit logging for sensitive operations.', weakResponseExample: 'The frontend can hide buttons that the user is not allowed to click, so the API does not need many permission checks.' },
  { id: 'tech-007', role: 'Fullstack Software Engineer', stage: 'Technical & Domain Depth', competency: 'Database Indexing and Query Design', difficulty: 'Senior', questionType: 'Technical', question: 'A frequently used query became slow as a table grew from thousands to tens of millions of rows. How do you investigate and fix it?', expectedCompetencies: ['Query-plan analysis', 'Index design', 'Operational trade-offs'], evaluationCriteria: ['Uses actual query plans and workload evidence', 'Explains composite-index ordering', 'Considers write cost and safe rollout'], idealStarResponse: 'I reproduce the query with representative parameters and inspect its execution plan, row estimates, joins, sort operations, and lock behavior. I design an index around the filter and ordering pattern, checking selectivity and whether a composite index can cover the query, then validate it in staging with production-like data. I also account for write amplification and create the index using an online or concurrent approach where the database supports it, then monitor latency and resource impact after rollout.', weakResponseExample: 'I would add indexes to every column involved in the query.' },
  { id: 'tech-008', role: 'Cloud & DevOps Engineer', stage: 'Technical & Domain Depth', competency: 'Kubernetes Workload Reliability', difficulty: 'Mid-Level', questionType: 'Technical', question: 'How do readiness probes, liveness probes, resource requests, and limits work together in Kubernetes?', expectedCompetencies: ['Traffic readiness', 'Failure recovery', 'Resource scheduling'], evaluationCriteria: ['Distinguishes readiness from liveness', 'Explains requests versus limits', 'Mentions avoiding harmful probe configuration'], idealStarResponse: 'Readiness determines whether a pod should receive traffic; liveness can restart a process that is genuinely stuck. Resource requests inform scheduling and limits constrain consumption, though overly tight limits can cause throttling or OOM kills. I configure probes around real application behavior, give startup-dependent services enough initial time, and use metrics to tune resources rather than treating restarts as normal health checks.', weakResponseExample: 'Both probes just restart pods, and requests are optional because Kubernetes will find enough CPU.' },
  { id: 'tech-009', role: 'Cloud & DevOps Engineer', stage: 'Technical & Domain Depth', competency: 'Infrastructure as Code', difficulty: 'Mid-Level', questionType: 'Technical', question: 'What practices make infrastructure-as-code changes safe and repeatable?', expectedCompetencies: ['Declarative state management', 'Review and plan workflow', 'Environment controls'], evaluationCriteria: ['Explains plan/review/apply separation', 'Addresses secrets and state access', 'Includes testing and rollback'], idealStarResponse: 'I keep infrastructure definitions versioned, modular, reviewed, and promoted through environments with a visible plan before apply. Remote state is encrypted, access-controlled, and locked to prevent concurrent changes; secrets come from a dedicated secret store rather than source control. Policy checks, ephemeral or sandbox validation, and clear rollback or recovery procedures make changes repeatable rather than dependent on a single operator.', weakResponseExample: 'I run the infrastructure command from my laptop and fix the configuration if it fails.' },
  { id: 'tech-010', role: 'AI & Data Platform Engineer', stage: 'Technical & Domain Depth', competency: 'Model Evaluation', difficulty: 'Entry', questionType: 'Technical', question: 'How would you evaluate a binary classification model before deciding whether it is ready to use?', expectedCompetencies: ['Train/validation/test separation', 'Appropriate metrics', 'Error analysis'], evaluationCriteria: ['Explains precision, recall, and threshold trade-offs', 'Checks a held-out test set', 'Considers class imbalance and slices'], idealStarResponse: 'I define the decision and cost of errors first, then use a held-out test set that reflects expected production data. Accuracy alone may be misleading, so I examine precision, recall, F1, PR-AUC or ROC-AUC as appropriate, choose a threshold based on the harm of false positives and negatives, and inspect performance across important user or data slices. I also compare to a simple baseline and document limitations before launch.', weakResponseExample: 'If the model has high training accuracy, it is ready.' },
  { id: 'tech-011', role: 'AI & Data Platform Engineer', stage: 'Technical & Domain Depth', competency: 'Data Pipeline Reliability', difficulty: 'Senior', questionType: 'Technical', question: 'How would you design a batch data pipeline so that retries do not create duplicate or inconsistent outputs?', expectedCompetencies: ['Idempotency', 'Atomic publication', 'Data quality checks'], evaluationCriteria: ['Defines stable input and output identities', 'Handles partial failure and retries', 'Includes lineage and monitoring'], idealStarResponse: 'I partition inputs by a stable business or time key and make each transformation deterministic for that partition. Outputs are written to a temporary location or versioned table, validated for schema, volume, and quality, then atomically published only when complete. The orchestrator records run state and input versions so retries either safely replace the same partition or are deduplicated; lineage and freshness alerts make failures visible.', weakResponseExample: 'If a job fails, rerun it and append the new output to the table.' },
  { id: 'tech-012', role: 'AI & Data Platform Engineer', stage: 'Technical & Domain Depth', competency: 'Feature Engineering and Leakage', difficulty: 'Senior', questionType: 'Technical', question: 'What is data leakage in machine learning, and how do you prevent it when building features?', expectedCompetencies: ['Temporal reasoning', 'Train-serving parity', 'Validation discipline'], evaluationCriteria: ['Defines leakage accurately', 'Gives a realistic example', 'Explains prevention in pipeline and evaluation'], idealStarResponse: 'Leakage occurs when a feature contains information unavailable at the time the prediction is meant to be made, producing unrealistically strong offline results. For example, a churn feature computed after cancellation would leak the label. I use point-in-time joins, time-based splits where appropriate, feature definitions with availability timestamps, and train-serving parity checks so the model sees only information that would exist in production.', weakResponseExample: 'Leakage is mainly when someone accidentally shares the model source code.' },
  { id: 'tech-013', role: 'Telecom & Network Systems Engineer', stage: 'Technical & Domain Depth', competency: 'Network Troubleshooting', difficulty: 'Entry', questionType: 'Technical', question: 'A user reports that an application is intermittently slow. How would you use the network troubleshooting model to narrow down the cause?', expectedCompetencies: ['Layered troubleshooting', 'Evidence collection', 'Hypothesis testing'], evaluationCriteria: ['Uses a methodical layer-by-layer approach', 'Mentions latency, loss, DNS, and path evidence', 'Avoids assuming the network is at fault'], idealStarResponse: 'I start by defining scope, timing, affected locations, and a baseline, then test the path systematically. I verify name resolution, reachability, latency and packet loss, transport behavior, and application timing while comparing a healthy path or user where possible. Packet captures, flow data, and device counters help distinguish network symptoms from server or application saturation, and each test should confirm or eliminate a hypothesis.', weakResponseExample: 'I would reboot the router first because intermittent slowness is usually networking.' },
  { id: 'tech-014', role: 'Telecom & Network Systems Engineer', stage: 'Technical & Domain Depth', competency: 'BGP Routing Fundamentals', difficulty: 'Senior', questionType: 'Technical', question: 'How does BGP choose between multiple routes, and what operational safeguards do you use when changing routing policy?', expectedCompetencies: ['Path attribute reasoning', 'Policy control', 'Safe rollout'], evaluationCriteria: ['Explains relevant attributes and local policy', 'Recognizes iBGP/eBGP operational concerns', 'Uses filtering and monitoring safeguards'], idealStarResponse: 'BGP route selection is policy-driven and considers attributes such as local preference, AS-path length, origin, MED in relevant contexts, and next-hop reachability; exact behavior should be understood for the vendor and design. I use explicit prefix and AS-path filters, maximum-prefix limits, peer templates, and staged changes with route visibility and traffic monitoring. Before a broad policy change, I validate intended advertisements and have a tested rollback path to reduce leak or blackhole risk.', weakResponseExample: 'BGP always picks the route with the fewest router hops, so policy is not very important.' },
  { id: 'tech-015', role: 'Fullstack Software Engineer', stage: 'Technical & Domain Depth', competency: 'Caching Consistency', difficulty: 'Senior', questionType: 'Technical', question: 'When would you cache application data, and how would you manage invalidation and stale data risks?', expectedCompetencies: ['Caching trade-offs', 'Invalidation strategies', 'Observability'], evaluationCriteria: ['Selects suitable data and layer', 'Explains TTL, events, or versioning', 'Addresses correctness and cache stampede'], idealStarResponse: 'I cache data when it is read frequently, expensive to compute, and can tolerate a defined freshness window. The strategy follows the correctness requirement: TTL may suit catalog data, while event invalidation or versioned keys may be needed for account-sensitive data. I protect against stampedes with request coalescing or controlled refresh, define cache metrics, and ensure the system still behaves correctly on cache misses or delayed invalidation.', weakResponseExample: 'Caching always makes systems faster, so I would cache every database response forever.' },

  // ==========================================
  // STAGE 4: SYSTEM DESIGN & SCENARIOS
  // ==========================================
  { id: 'des-002', role: 'Fullstack Software Engineer', stage: 'System Design & Scenarios', competency: 'Scalable Notification Delivery', difficulty: 'Mid-Level', questionType: 'Scenario-Based', question: 'Design a notification service that delivers email, push, and in-app messages while respecting user preferences and retrying transient failures.', expectedCompetencies: ['Asynchronous design', 'Preference enforcement', 'Delivery reliability'], evaluationCriteria: ['Separates API, queue, workers, and provider adapters', 'Handles idempotency and retries', 'Includes observability and opt-out controls'], idealStarResponse: 'I would accept requests through an authenticated API, validate a stable notification id, resolve user preferences, and publish channel-specific work to a durable queue. Independent workers call provider adapters with idempotency keys, bounded retries, backoff, and a dead-letter path; delivery status is recorded for audit and user visibility. Preference checks happen before each send, while metrics track queue lag, provider errors, and delivery outcomes.', weakResponseExample: 'A web server can call all email and push providers directly during the user request.' },
  { id: 'des-003', role: 'Fullstack Software Engineer', stage: 'System Design & Scenarios', competency: 'Multi-Tenant SaaS Isolation', difficulty: 'Senior', questionType: 'Scenario-Based', question: 'Design a multi-tenant SaaS application that must isolate customer data while supporting growth from ten to ten thousand tenants.', expectedCompetencies: ['Tenant isolation', 'Scalability', 'Operational controls'], evaluationCriteria: ['Defines tenant identity and authorization boundaries', 'Compares shared and dedicated storage options', 'Covers migrations, observability, and noisy neighbors'], idealStarResponse: 'I establish tenant identity at authentication and enforce it in every service and query, never trusting a client-supplied tenant alone. A shared database with tenant keys and row-level controls can serve many tenants initially, while large or regulated customers may justify dedicated partitions or databases behind the same abstraction. I add per-tenant quotas, audit logs, encryption boundaries, migration tooling, and metrics that expose noisy-neighbor behavior before it affects others.', weakResponseExample: 'I would add a tenantId in the frontend request and trust each customer not to change it.' },
  { id: 'des-004', role: 'Fullstack Software Engineer', stage: 'System Design & Scenarios', competency: 'File Upload Platform', difficulty: 'Entry', questionType: 'Scenario-Based', question: 'Design a secure file-upload workflow for users who can upload documents up to 100 MB.', expectedCompetencies: ['Direct object storage upload', 'Security validation', 'Asynchronous processing'], evaluationCriteria: ['Avoids routing large files through the application unnecessarily', 'Uses signed upload controls and validation', 'Handles scanning and processing status'], idealStarResponse: 'I would issue a short-lived, scoped signed upload URL after authorizing the user and validating metadata such as size and content type. The client uploads directly to object storage, then an event triggers malware scanning and document processing in an isolated worker before the file becomes available. Stored objects use private access, encryption, immutable identifiers, and status tracking so users see whether processing succeeded without exposing unscanned content.', weakResponseExample: 'I would base64 encode the whole file and store it in the primary database.' },
  { id: 'des-005', role: 'Cloud & DevOps Engineer', stage: 'System Design & Scenarios', competency: 'Multi-Region Resilience', difficulty: 'Lead / Principal', questionType: 'Scenario-Based', question: 'Design a multi-region service with a 99.99% availability target and explain how you would test its failover behavior.', expectedCompetencies: ['Availability design', 'Data consistency trade-offs', 'Disaster-recovery testing'], evaluationCriteria: ['Defines RTO/RPO and failure assumptions', 'Addresses traffic, state, and dependencies', 'Uses practiced failover and observability'], idealStarResponse: 'I begin with explicit RTO, RPO, regional-failure assumptions, and the services that must remain available. Stateless workloads can run active-active behind health-aware traffic management, while data replication and write routing must match the consistency requirement; some workflows may need active-passive or degraded modes. I automate failover, continuously test backups and restore, run controlled regional-failure exercises, and measure recovery against the stated objectives rather than assuming replication alone proves resilience.', weakResponseExample: 'I would deploy the same application in two regions and use a load balancer, so it is automatically highly available.' },
  { id: 'des-006', role: 'Cloud & DevOps Engineer', stage: 'System Design & Scenarios', competency: 'Secure CI/CD Platform', difficulty: 'Senior', questionType: 'Scenario-Based', question: 'Design a CI/CD pipeline for multiple services that supports fast releases without allowing unreviewed or vulnerable code into production.', expectedCompetencies: ['Supply-chain security', 'Progressive delivery', 'Policy automation'], evaluationCriteria: ['Includes source controls and artifact provenance', 'Uses tests, scans, and promotion gates', 'Explains rollback and auditability'], idealStarResponse: 'The pipeline starts with protected branches, peer review, and reproducible builds that produce signed, immutable artifacts. Automated unit, integration, dependency, secret, and container checks run before an artifact is promoted through environments with policy gates and scoped credentials. Production uses progressive delivery, health-based rollback, deployment audit records, and separated approval rights so speed comes from automation and reliable evidence rather than bypassing controls.', weakResponseExample: 'Developers should SSH to production when they need to deploy a quick fix.' },
  { id: 'des-007', role: 'AI & Data Platform Engineer', stage: 'System Design & Scenarios', competency: 'Real-Time Feature Serving', difficulty: 'Senior', questionType: 'Scenario-Based', question: 'Design a real-time feature platform for a fraud model that needs consistent offline training and low-latency online inference.', expectedCompetencies: ['Offline/online feature parity', 'Latency design', 'Feature governance'], evaluationCriteria: ['Explains point-in-time correctness', 'Separates batch and online serving paths', 'Includes freshness, monitoring, and fallback'], idealStarResponse: 'I define features once with ownership, entity keys, timestamps, and availability rules, then materialize them to an offline store for training and an online store for low-latency lookup. Training uses point-in-time joins to avoid leakage, while the serving path fetches versioned features and logs inputs and predictions for monitoring. Freshness checks, backfills, access controls, and a safe fallback decision protect the system when a feature is late or unavailable.', weakResponseExample: 'I would keep all features in a notebook and query the training database directly for every user request.' },
  { id: 'des-008', role: 'AI & Data Platform Engineer', stage: 'System Design & Scenarios', competency: 'RAG Platform Governance', difficulty: 'Lead / Principal', questionType: 'Scenario-Based', question: 'Design an internal RAG assistant that can answer from company documents while protecting permissions and measuring answer quality.', expectedCompetencies: ['Retrieval architecture', 'Authorization-aware indexing', 'Evaluation and safety'], evaluationCriteria: ['Enforces access before retrieval and generation', 'Uses grounded citations and quality evaluation', 'Covers ingestion, freshness, and feedback'], idealStarResponse: 'I would ingest approved documents through a versioned pipeline that extracts content, metadata, owners, and access-control labels before chunking and indexing. At query time, identity and permissions filter candidates before hybrid retrieval and reranking; the model receives only authorized context and must cite it or abstain. Offline evaluation sets, online feedback, retrieval and groundedness metrics, audit logs, and document-refresh jobs make quality and governance operational rather than prompt-only concerns.', weakResponseExample: 'I would put every company document into a vector database and let the model decide what users can see.' },
  { id: 'des-009', role: 'AI & Data Platform Engineer', stage: 'System Design & Scenarios', competency: 'Streaming Analytics', difficulty: 'Mid-Level', questionType: 'Scenario-Based', question: 'Design a streaming analytics pipeline that reports near-real-time product events and corrects late-arriving data.', expectedCompetencies: ['Event-time processing', 'Data quality', 'Serving architecture'], evaluationCriteria: ['Separates ingestion, processing, and serving', 'Explains watermarks or late data handling', 'Includes idempotency and operational metrics'], idealStarResponse: 'Events enter a durable log with schema validation and stable event ids, then a stream processor aggregates by event time using watermarks and an allowed lateness policy. Late events update or reconcile affected windows rather than silently disappearing, while idempotent sinks prevent duplicates. A low-latency serving store powers dashboards, and batch reconciliation plus freshness, lag, and invalid-event metrics makes the reported numbers trustworthy.', weakResponseExample: 'I would update a dashboard directly whenever an event arrives and ignore events that show up late.' },
  { id: 'des-010', role: 'Telecom & Network Systems Engineer', stage: 'System Design & Scenarios', competency: 'Network Automation Platform', difficulty: 'Senior', questionType: 'Scenario-Based', question: 'Design a network automation platform that safely deploys configuration changes across thousands of devices.', expectedCompetencies: ['Intent and validation', 'Staged rollout', 'Audit and rollback'], evaluationCriteria: ['Separates desired state from execution', 'Uses pre/post checks and change windows', 'Handles partial failures safely'], idealStarResponse: 'I represent approved intent and device-specific rendering separately, validate syntax and policy before execution, and store an immutable change plan with peer approval. The executor rolls out in small cohorts, captures prechecks and postchecks, pauses on defined error thresholds, and uses known-good configuration or compensating actions for rollback. Device inventory, credentials, audit logs, and telemetry are centralized so every change is traceable and partial failure does not become an uncontrolled fleet-wide event.', weakResponseExample: 'I would run the same command over SSH on every device at once and check the logs afterward.' },
  { id: 'des-011', role: 'Telecom & Network Systems Engineer', stage: 'System Design & Scenarios', competency: 'Edge Connectivity Resilience', difficulty: 'Lead / Principal', questionType: 'Scenario-Based', question: 'Design connectivity for remote edge sites that must keep local operations running when the WAN is unreliable.', expectedCompetencies: ['Offline-first design', 'Redundant connectivity', 'Secure synchronization'], evaluationCriteria: ['Identifies local versus central responsibilities', 'Handles failover and eventual synchronization', 'Covers monitoring and security'], idealStarResponse: 'I design each site to preserve critical local functions with a local gateway, cached policy or data, and a controlled store-and-forward queue for central synchronization. Diverse WAN paths with health-based failover reduce outage probability, but applications must also tolerate partitions and reconcile idempotently when connectivity returns. Central monitoring tracks path quality and queue age, while encrypted tunnels, device identity, and least-privilege controls protect remote management.', weakResponseExample: 'I would require every local operation to call the central data center so all data stays consistent.' },
  { id: 'des-012', role: 'Fullstack Software Engineer', stage: 'System Design & Scenarios', competency: 'Rate Limiting and Abuse Prevention', difficulty: 'Mid-Level', questionType: 'Scenario-Based', question: 'Design API rate limiting for a public service that must protect itself from abuse without harming legitimate customers.', expectedCompetencies: ['Rate-limit algorithms', 'Identity and fairness', 'Observability'], evaluationCriteria: ['Chooses a suitable enforcement layer', 'Explains keys, quotas, and responses', 'Handles distributed consistency and exceptions'], idealStarResponse: 'I would enforce limits near the edge and again where expensive operations need protection, keying primarily on authenticated tenant or user while considering IP signals for anonymous traffic. A token-bucket or sliding-window approach permits controlled bursts and returns clear retry information; trusted integrations receive explicit, auditable tiers rather than hidden bypasses. Shared counters must be resilient and observable, with dashboards for rejected traffic, false positives, and endpoint-specific pressure.', weakResponseExample: 'I would block any IP that makes more than ten requests, regardless of endpoint or customer plan.' },
  { id: 'des-013', role: 'Cloud & DevOps Engineer', stage: 'System Design & Scenarios', competency: 'Observability Platform', difficulty: 'Mid-Level', questionType: 'Scenario-Based', question: 'Design observability for a microservices application so on-call engineers can find the cause of a user-facing error quickly.', expectedCompetencies: ['Logs, metrics, and traces', 'Correlation', 'Actionable alerting'], evaluationCriteria: ['Connects telemetry with request context', 'Defines service and user-impact signals', 'Avoids noisy alerts'], idealStarResponse: 'Each service emits structured logs, metrics, and distributed traces with a correlation id propagated across boundaries, while sensitive fields are redacted. I define dashboards around latency, errors, saturation, dependency health, and user journeys, then alert on symptoms tied to SLOs rather than every component fluctuation. Runbooks link alerts to relevant traces, logs, recent deployments, and owners so responders can move from impact to likely cause efficiently.', weakResponseExample: 'I would store all logs forever and alert whenever CPU reaches 50 percent.' },
  { id: 'des-014', role: 'AI & Data Platform Engineer', stage: 'System Design & Scenarios', competency: 'ML Monitoring and Rollback', difficulty: 'Senior', questionType: 'Scenario-Based', question: 'Design monitoring and rollback for a model that influences customer support ticket routing.', expectedCompetencies: ['Model and system monitoring', 'Human fallback', 'Safe deployment'], evaluationCriteria: ['Monitors quality, drift, and operational health', 'Defines thresholds and ownership', 'Supports rollback or shadow/canary rollout'], idealStarResponse: 'I launch through shadow or canary traffic with a known rule-based or human-routing fallback, logging model version, features, prediction, confidence, and later outcome where available. Monitoring covers latency, errors, feature freshness, confidence distribution, drift, routing accuracy, and impact across relevant segments. Predefined thresholds pause expansion or roll back to the prior version, while a review process handles sustained quality concerns and keeps humans in the loop for low-confidence cases.', weakResponseExample: 'Once the model is deployed, I would only monitor server uptime because the predictions come from the trained model.' },
  { id: 'des-015', role: 'Engineering Manager / Tech Lead', stage: 'System Design & Scenarios', competency: 'Platform Modernization Strategy', difficulty: 'Lead / Principal', questionType: 'Scenario-Based', question: 'You inherit a business-critical monolith with frequent releases failures. How would you design a modernization strategy without stopping feature delivery?', expectedCompetencies: ['Incremental architecture strategy', 'Risk management', 'Organizational alignment'], evaluationCriteria: ['Avoids big-bang rewrite', 'Prioritizes seams and measurable outcomes', 'Addresses team topology and migration controls'], idealStarResponse: 'I first map failure modes, deployment bottlenecks, domain boundaries, and the business capabilities most constrained by the monolith. Rather than begin with a rewrite, I create a thin modernization path: improve observability and tests, isolate a high-value boundary behind a stable interface, and migrate that capability with measurable reliability and delivery targets. Teams retain feature delivery through a shared roadmap, feature flags, compatibility contracts, and regular evidence reviews; each extracted service must reduce a real constraint, not merely change technology.', weakResponseExample: 'I would split the whole monolith into microservices immediately so each team can move faster.' },

  // ==========================================
  // STAGE 5: EXECUTIVE & CLIENT COMMUNICATION
  // ==========================================
  { id: 'exec-002', role: 'Cloud & DevOps Engineer', stage: 'Executive & Client Communication', competency: 'Reliability Business Case', difficulty: 'Senior', questionType: 'Scenario-Based', question: 'How would you explain the business case for investing in reliability work to a leadership team focused on new features?', expectedCompetencies: ['Business translation', 'Risk quantification', 'Prioritization'], evaluationCriteria: ['Connects reliability to customer and revenue outcomes', 'Uses understandable evidence', 'Proposes an incremental investment'], idealStarResponse: 'I would frame reliability as protection for revenue, trust, and engineering capacity rather than as infrastructure polish. I would show incident frequency, customer impact, recovery cost, and the feature-delivery time lost to avoidable support work, then propose a small prioritized plan with target SLOs and expected risk reduction. Leadership can then compare a transparent investment against the cost of recurring failure.', weakResponseExample: 'Reliability is important because engineers like clean systems, so it should be funded.' },
  { id: 'exec-003', role: 'AI & Data Platform Engineer', stage: 'Executive & Client Communication', competency: 'Explaining Model Limits', difficulty: 'Mid-Level', questionType: 'Scenario-Based', question: 'How would you explain to a non-technical stakeholder why an AI assistant cannot guarantee that every answer is correct?', expectedCompetencies: ['Plain-language communication', 'Risk mitigation', 'Expectation setting'], evaluationCriteria: ['Avoids unnecessary jargon', 'Explains uncertainty and groundedness', 'Offers practical safeguards'], idealStarResponse: 'I would describe the assistant as a helpful system that predicts useful language from approved information, not as an infallible source of truth. Its answers can be made safer by retrieving authorized source material, showing citations, declining when evidence is insufficient, and routing high-impact cases to people. We measure and improve it over time, but we should set expectations that it supports judgment rather than replaces accountability.', weakResponseExample: 'The model is probabilistic and uses tokens, so hallucinations are unavoidable.' },
  { id: 'exec-004', role: 'Fullstack Software Engineer', stage: 'Executive & Client Communication', competency: 'Incident Executive Update', difficulty: 'Mid-Level', questionType: 'Scenario-Based', question: 'Give a two-minute update to an executive during an active customer-facing outage.', expectedCompetencies: ['Concise communication', 'Impact-first framing', 'Credible next steps'], evaluationCriteria: ['States scope and customer impact first', 'Separates known facts from investigation', 'Provides next update and mitigation status'], idealStarResponse: 'We are investigating elevated checkout failures affecting approximately twelve percent of transactions since 10:05. The team has isolated the issue to the latest payment-service deployment and is rolling back now; we expect to confirm recovery within ten minutes. No data loss has been identified, customer support has an approved message, and I will provide the next update at 10:25 with recovery metrics and the initial root-cause assessment.', weakResponseExample: 'There is a problem with the servers, but the engineers are looking into it and it should be fixed soon.' },
  { id: 'exec-005', role: 'Telecom & Network Systems Engineer', stage: 'Executive & Client Communication', competency: 'Network Modernization Narrative', difficulty: 'Senior', questionType: 'Scenario-Based', question: 'How would you explain a network automation initiative to a client concerned that automation will make changes less safe?', expectedCompetencies: ['Trust-building', 'Risk framing', 'Business value'], evaluationCriteria: ['Acknowledges the concern', 'Explains controls in non-technical language', 'Connects automation to consistency and recovery'], idealStarResponse: 'I would begin by agreeing that uncontrolled automation would be risky. The initiative replaces repetitive, error-prone manual steps with approved templates, peer review, pre-change checks, staged rollout, and automatic pause or rollback signals; people remain accountable for policy and exceptions. The value is more consistent service, faster recovery, and a complete audit trail—not removing judgment from critical changes.', weakResponseExample: 'Automation is safer because computers do not make mistakes, so the client should not worry.' },
  { id: 'exec-006', role: 'AI & Data Platform Engineer', stage: 'Executive & Client Communication', competency: 'Data Investment Prioritization', difficulty: 'Senior', questionType: 'Scenario-Based', question: 'A client asks for a sophisticated AI solution, but their source data is incomplete and inconsistent. How do you advise them?', expectedCompetencies: ['Consultative judgment', 'Value sequencing', 'Clear trade-offs'], evaluationCriteria: ['Diagnoses readiness without dismissing ambition', 'Proposes a phased plan', 'Defines decision metrics'], idealStarResponse: 'I would validate the goal and explain that model sophistication cannot compensate for unreliable inputs in a high-stakes workflow. I would recommend a phased investment: profile the data, improve the few fields that drive the decision, establish quality ownership and baselines, then pilot a constrained use case against agreed success measures. This gives the client an early learning outcome while protecting them from a costly model that cannot be trusted.', weakResponseExample: 'We should train the largest available model first and clean the data later if accuracy is low.' },
  { id: 'exec-007', role: 'Fullstack Software Engineer', stage: 'Executive & Client Communication', competency: 'Trade-off Communication', difficulty: 'Senior', questionType: 'Scenario-Based', question: 'How would you present a decision between a faster launch with known limitations and a delayed launch with broader capability?', expectedCompetencies: ['Decision framing', 'Risk transparency', 'Recommendation clarity'], evaluationCriteria: ['Defines options in customer outcomes', 'States assumptions and mitigations', 'Makes a clear recommendation'], idealStarResponse: 'I would present the decision as two customer outcomes, not two engineering preferences: a focused launch that solves the highest-value case now with explicit limits, or a later launch that covers more scenarios. I would quantify reachable users, known risks, support needs, and the cost of delay, then recommend the option that best meets the agreed objective. If we launch narrowly, feature flags, measurement, and a committed follow-up milestone make the limitation deliberate rather than hidden.', weakResponseExample: 'The engineering team prefers the delayed option because it is more elegant.' },
  { id: 'exec-008', role: 'Cloud & DevOps Engineer', stage: 'Executive & Client Communication', competency: 'Cloud Cost Optimization', difficulty: 'Mid-Level', questionType: 'Scenario-Based', question: 'How would you explain a cloud-cost optimization proposal without making it sound like a risky cost-cutting exercise?', expectedCompetencies: ['Financial literacy', 'Operational safeguards', 'Clear ROI'], evaluationCriteria: ['Separates waste from capacity needed for reliability', 'Explains staged validation', 'Uses measurable savings and risk metrics'], idealStarResponse: 'I would distinguish waste from resilience: the goal is to remove idle or mismatched spend while preserving the capacity that protects customer experience. The proposal would start with visibility by service, then low-risk actions such as rightsizing nonproduction workloads, storage lifecycle policies, and scheduled environments, each measured against latency, error rate, and availability guardrails. Savings are reported alongside service health so cost reduction never becomes a hidden reliability trade.', weakResponseExample: 'We should reduce all cloud resources by twenty percent and see what breaks.' },
  { id: 'exec-009', role: 'Engineering Manager / Tech Lead', stage: 'Executive & Client Communication', competency: 'Roadmap Risk Management', difficulty: 'Lead / Principal', questionType: 'Scenario-Based', question: 'How would you communicate that a strategic roadmap date is at risk without creating surprise or blame?', expectedCompetencies: ['Early escalation', 'Options-based communication', 'Accountability'], evaluationCriteria: ['States evidence and uncertainty clearly', 'Offers mitigation options', 'Sets a decision and update cadence'], idealStarResponse: 'I communicate risk as soon as the evidence changes, with the customer or business impact, confidence level, and drivers made explicit. I bring options—for example reduce scope, add a dependency decision, sequence a milestone, or move the date—along with the trade-offs of each rather than merely reporting bad news. I own the plan, name the next decision point, and keep a predictable update cadence so leadership can act before the risk becomes a surprise.', weakResponseExample: 'I wait until the deadline is close so I can be sure the team really cannot make it.' },
  { id: 'exec-010', role: 'Telecom & Network Systems Engineer', stage: 'Executive & Client Communication', competency: 'Explaining Capacity Planning', difficulty: 'Mid-Level', questionType: 'Scenario-Based', question: 'How would you explain a capacity-planning recommendation to a client who sees no current outage and questions the expense?', expectedCompetencies: ['Plain-language risk explanation', 'Evidence-led recommendation', 'Business continuity'], evaluationCriteria: ['Uses demand and headroom evidence', 'Explains consequences without fearmongering', 'Presents phased options'], idealStarResponse: 'I would show the observed traffic trend, peak utilization, and the margin remaining before service quality degrades, translating those into potential customer and operational impact during a growth event. Rather than request a single large purchase, I would offer phased capacity options tied to trigger thresholds and review dates. That makes the investment a planned protection for growth and continuity, not an abstract technical preference.', weakResponseExample: 'We need more bandwidth because the network team says so.' },
  { id: 'exec-011', role: 'AI & Data Platform Engineer', stage: 'Executive & Client Communication', competency: 'Responsible AI Incident Response', difficulty: 'Lead / Principal', questionType: 'Scenario-Based', question: 'A client reports that an AI feature produced an inappropriate result. How would you lead the first response conversation?', expectedCompetencies: ['Empathy', 'Fact-based accountability', 'Safety response'], evaluationCriteria: ['Acknowledges impact without speculation', 'Explains immediate containment and investigation', 'Sets remediation and communication expectations'], idealStarResponse: 'I would acknowledge the impact and thank the client for raising it, without speculating about root cause before we have evidence. I would explain the immediate containment action—such as disabling the affected workflow or requiring review—then outline the investigation into inputs, retrieval, model behavior, and safeguards. We would agree on update timing and remediation criteria, including validation before re-enabling the feature, so the response demonstrates accountability rather than defensiveness.', weakResponseExample: 'AI sometimes makes mistakes, so the client should understand that this is normal.' },
  { id: 'exec-012', role: 'Fullstack Software Engineer', stage: 'Executive & Client Communication', competency: 'Accessibility Advocacy', difficulty: 'Entry', questionType: 'Scenario-Based', question: 'How would you explain why accessibility should be included in a product release plan to a stakeholder focused on speed?', expectedCompetencies: ['Inclusive product thinking', 'Business communication', 'Practical prioritization'], evaluationCriteria: ['Connects accessibility to users and quality', 'Avoids treating it as optional polish', 'Proposes actionable integration'], idealStarResponse: 'I would explain that accessibility helps people complete the same core task reliably and often improves usability for everyone, especially under different devices or conditions. Building it into design, acceptance criteria, and automated checks is usually less costly than retrofitting it after launch, and it reduces customer and compliance risk. We can prioritize the most important journeys first while making accessibility a normal quality requirement for new work.', weakResponseExample: 'Accessibility is nice to have, but we can add it after the main feature ships.' },
  { id: 'exec-013', role: 'Cloud & DevOps Engineer', stage: 'Executive & Client Communication', competency: 'Security Risk Communication', difficulty: 'Senior', questionType: 'Scenario-Based', question: 'How would you communicate a security vulnerability that has been identified but not yet exploited?', expectedCompetencies: ['Risk communication', 'Calm urgency', 'Remediation planning'], evaluationCriteria: ['Explains exposure and uncertainty accurately', 'Prioritizes containment and patching', 'Avoids unnecessary technical detail or false reassurance'], idealStarResponse: 'I would state what we know: the affected systems, the conditions required for exploitation, whether evidence of compromise exists, and the customer or regulatory impact if it were exploited. I would then outline immediate containment, patch and validation steps, owners, and when the next update will arrive. The tone should be urgent and factual—neither minimizing the risk nor claiming certainty we do not have.', weakResponseExample: 'There is a CVE, but we do not think it matters, so we will patch it when the team has time.' },
  { id: 'exec-014', role: 'Engineering Manager / Tech Lead', stage: 'Executive & Client Communication', competency: 'Build Versus Buy Decision', difficulty: 'Lead / Principal', questionType: 'Scenario-Based', question: 'How would you present a build-versus-buy recommendation for a core platform capability?', expectedCompetencies: ['Strategic analysis', 'Total cost of ownership', 'Decision communication'], evaluationCriteria: ['Defines differentiated versus commodity value', 'Compares time, cost, risk, and control', 'Recommends a reversible path where possible'], idealStarResponse: 'I begin with the capability’s strategic value: if it differentiates the customer experience or encodes unique domain knowledge, building may be justified; if it is commodity, a proven product can accelerate delivery. I compare implementation and integration cost, operating burden, security, vendor risk, roadmap control, and exit options over a realistic horizon. My recommendation includes a short validation or pilot path where uncertainty remains, with clear success criteria instead of an irreversible ideology.', weakResponseExample: 'We should build because engineers prefer owning the code, or buy because vendors are always faster.' },
  { id: 'exec-015', role: 'Telecom & Network Systems Engineer', stage: 'Executive & Client Communication', competency: 'Client Recovery Leadership', difficulty: 'Lead / Principal', questionType: 'Scenario-Based', question: 'After a major service disruption, how would you present the recovery plan and restore client confidence?', expectedCompetencies: ['Executive presence', 'Transparent accountability', 'Sustainable remediation'], evaluationCriteria: ['Acknowledges business impact', 'Separates immediate recovery from systemic prevention', 'Defines milestones and proof of progress'], idealStarResponse: 'I would begin with the client impact and our responsibility, then give a concise fact-based timeline of what happened, what is stable now, and what remains under observation. The recovery plan distinguishes immediate safeguards from root-cause remediation, assigns accountable owners and dates, and includes evidence the client can review such as resilience tests, service metrics, and progress checkpoints. Confidence returns through transparent follow-through, not a one-time apology.', weakResponseExample: 'I would apologize, assure the client it will not happen again, and avoid technical details so they do not worry.' }
];

